# idea: retinal input transforms (gamma+saturation+contrast) feeding a per-family-compressed color-opponent + foveal-zoom Gabor + HOG + color-histogram + random-CNN code
"""
An untrained ventral-stream front-end for macaque EVC+IT on natural (NSD) images. Everything is
analytic or random-but-fixed, per-sample, deterministic; no training, no cross-image statistics, no
pretrained weights. RGB -> luminance + red-green / blue-yellow opponent channels + chroma.

The decisive levers on this dataset (found by ablation):
  0. RETINAL INPUT TRANSFORMS applied once to the raw pixels before any feature: a light-adaptation
     gamma (pixels^0.6), a per-pixel saturation boost (push RGB away from the pixel mean, power 1.8),
     and a global contrast tone-curve toward mid-gray (gain 0.7). Stacked, they reshape the intensity
     /chroma distribution the whole model reads out and are a large late gain (esp. for IT);
  1. a per-family COMPRESSIVE power nonlinearity sign(f)*|f|^p with p tuned per feature family
     (~0.26-0.34) (matches neural response
     compression; roughly doubles held-out predictivity vs raw features and lets heterogeneous
     families combine constructively instead of high-magnitude ones dominating the single-alpha ridge);
  2. a FOVEAL-ZOOM pyramid: NSD images have a central object, so a cascade of concentric center
     crops (0.6 -> 0.12 of the frame), each read out with fine opponent grids and avg+max-pooled
     luminance/opponent Gabor energy, adds the single largest IT+EVC gain -- progressively finer
     detail on the object core.

Feature families (all compressed, concatenated for the ridge):
  A. color-opponent retinotopic pyramid + soft 2-D chromatic histogram + luminance/opponent Gabor
     complex-cell energy (the "rich" base);
  B. a single fixed-seed color-input random CNN read out globally (a cheap EVC/high-level tap);
  C. absolute-color marginal histograms (surface/material identity, not just opponent contrast);
  D. a 4-crop foveal-zoom stack: opponent grids + avg/max foveal luminance & opponent Gabor energy.
  E. histogram-of-oriented-gradients (HOG) shape descriptors on luminance + opponents + the foveal core.
"""
import math

import torch
import torch.nn.functional as F

P = 0.28                      # compressive exponent for the CNN / absolute-color histogram families
P_RICH = 0.34                 # the color-opponent "rich" base wants the weakest compression
P_FOV = 0.26                  # the foveal-zoom stack wants the strongest compression
INPUT_GAMMA = 0.6            # retinal light-adaptation gamma on the raw pixels before any feature
SATURATION = 1.8             # per-pixel saturation boost (push RGB away from its pixel mean) after gamma
CONTRAST_GAIN = 0.7          # global luminance contrast toward mid-gray (a compressive tone curve)
# per-family gains (relative weighting into the single-alpha ridge; global scale is alpha-invariant
# but RELATIVE family scale shifts each family's effective regularization)
G_RICH = 1.0
G_CNN = 1.0
G_ABS = 1.8
G_FOV = 1.0
G_HOG = 3.0
# shared Gabor banks
LUM_WL = (3.0, 6.0, 12.0)
LUM_ORI = 8
OPP_WL = (6.0, 12.0)
OPP_ORI = 6
SIGMA_RATIO = 0.56
# rich base
PYR_GRIDS = (2, 4, 8)
LUM_EGRID = 6
OPP_EGRID = 4
HIST_BINS = 12
HIST_POOL = 32
HIST_SIGMA = 0.16
# absolute-color histograms
ABS_BINS = 16
ABS_POOL = 24
ABS_SIGMA = 0.06
# random CNN (global tap)
CNN_CHS = (4, 56, 112, 160, 160)
CNN_GRIDS = (4, 2, 1, 1)
CNN_SEED = 1
# foveal-zoom crops: (fraction of frame, opponent grid, gabor grid)
FOVEA = ((0.6, 6, 3), (0.4, 5, 3), (0.25, 6, 5), (0.12, 6, 5))
FOV_ORI = 7                 # orientations for the foveal luminance Gabor bank
FOV_HIST_POOL = 12          # downsample for the per-crop foveal color-palette histogram
# histogram of oriented gradients (a shape descriptor complementary to Gabor energy)
HOG_BINS = 9
HOG_SIGMA = 0.5
HOG_BLUR = (2.0, 4.0)       # extra full-frame HOG at these Gaussian pre-blur scales (multi-scale contour)
SUBCHUNK = 128


def _gabor_pair(wavelength, theta, sigma, gamma=0.5):
    half = int(math.ceil(3.0 * sigma))
    coords = torch.arange(-half, half + 1, dtype=torch.float32)
    y, x = torch.meshgrid(coords, coords, indexing="ij")
    xr = x * math.cos(theta) + y * math.sin(theta)
    yr = -x * math.sin(theta) + y * math.cos(theta)
    env = torch.exp(-(xr ** 2 + (gamma ** 2) * yr ** 2) / (2.0 * sigma ** 2))
    arg = 2.0 * math.pi * xr / wavelength
    even = env * torch.cos(arg)
    odd = env * torch.sin(arg)
    return even - even.mean(), odd - odd.mean()


def _spow(f, p=P):
    return torch.sign(f) * (f.abs() + 1e-6) ** p


class Model:
    name = "retinal-input-compressive-foveal-color-gabor"
    idea = "retinal input transforms (gamma+saturation+contrast) feeding a per-family-compressed color-opponent + foveal-zoom Gabor + HOG + color-histogram + random-CNN code"
    description = (
        "The raw pixels first pass RETINAL INPUT TRANSFORMS: light-adaptation gamma (pixels^0.6), a "
        "per-pixel saturation boost (push RGB from the pixel mean, power 1.8), and a contrast "
        "tone-curve toward mid-gray (gain 0.7). Then RGB -> luminance + red-green / blue-yellow "
        "opponent channels + chroma, and the model concatenates, each under a per-family compressive "
        "power law (rich base p=0.34, CNN/color histograms p=0.28, foveal & HOG p=0.26/0.28): (A) a "
        "color-opponent retinotopic pyramid (2/4/8/12), a soft 12x12 (RG,BY) chromatic histogram, and "
        "luminance (8 ori x 3 SF) and opponent (6 ori x 2 SF) Gabor complex-cell energy; (B) one "
        "fixed-seed color-input random CNN read out globally; (C) tight absolute-color marginal "
        "histograms over luminance/R/G/B/chroma and RG/BY; (D) a 4-crop foveal-zoom stack (concentric "
        "center crops 0.6/0.4/0.25/0.12), each with fine opponent grids + avg/max luminance & opponent "
        "Gabor energy + a foveal color palette; (E) multi-scale HOG shape descriptors on luminance, "
        "opponents, and two central crops. Untrained, per-sample, deterministic.")
    insight = (
        "Two levers dominate on this IT+EVC dataset: a retinal light-adaptation INPUT gamma "
        "(pixels^0.55, applied once before all features -- the single biggest late win, +0.005 and "
        "the first thing to move pure-IT predictivity) stacked with per-family compressive |f|^p "
        "nonlinearities (matches neural firing compression, makes heterogeneous families combine), "
        "plus a FOVEAL-ZOOM pyramid -- a cascade of ever-tighter center crops with fine Gabor/color "
        "readout, since NSD objects are central. Absolute-color surface histograms, HOG shape "
        "descriptors, and a globally-pooled random CNN add smaller consistent gains; 2nd-order "
        "scattering and global texture correlations were redundant. Next: tune input gamma per "
        "channel, sharper innermost crop under the D_out cap, or per-region readout.")
    n_params = 0

    def __init__(self):
        self._built = False

    def _build(self, device):
        self._lum = []
        for wl in LUM_WL:
            for k in range(LUM_ORI):
                e, o = _gabor_pair(wl, math.pi * k / LUM_ORI, SIGMA_RATIO * wl)
                self._lum.append((e.to(device), o.to(device)))
        self._opp = []
        for wl in OPP_WL:
            for k in range(OPP_ORI):
                e, o = _gabor_pair(wl, math.pi * k / OPP_ORI, SIGMA_RATIO * wl)
                self._opp.append((e.to(device), o.to(device)))
        self._flum = []                       # foveal luminance bank (FOV_ORI orientations)
        for wl in LUM_WL:
            for k in range(FOV_ORI):
                e, o = _gabor_pair(wl, math.pi * k / FOV_ORI, SIGMA_RATIO * wl)
                self._flum.append((e.to(device), o.to(device)))
        g = torch.Generator().manual_seed(CNN_SEED)
        self._cnn_w = []
        for i in range(len(CNN_CHS) - 1):
            k = 5 if i == 0 else 3
            w = torch.randn(CNN_CHS[i + 1], CNN_CHS[i], k, k, generator=g) / math.sqrt(CNN_CHS[i] * k * k)
            self._cnn_w.append(w.to(device))
        self._hc = torch.linspace(0.0, 1.0, ABS_BINS, device=device)
        self._oc = torch.linspace(-1.0, 1.0, ABS_BINS, device=device)
        self._centers = torch.linspace(-1.0, 1.0, HIST_BINS, device=device)
        n = sum(e.numel() + o.numel() for e, o in self._lum)
        n += sum(e.numel() + o.numel() for e, o in self._opp)
        n += sum(e.numel() + o.numel() for e, o in self._flum)
        n += sum(w.numel() for w in self._cnn_w)
        self.n_params = int(n)
        self._built = True

    @staticmethod
    def _to_images(X):
        n, d = X.shape
        side = int(round((d / 3) ** 0.5))
        return X.reshape(n, side, side, 3).permute(0, 3, 1, 2).contiguous()

    @staticmethod
    def _saturate(X):
        """Per-pixel saturation boost (push each RGB channel away from its pixel mean by a power > 1)
        followed by a global contrast tone-curve toward mid-gray. Both are per-sample input
        nonlinearities that, stacked with the input gamma, further compress the pixel distribution
        into the range the fixed histogram/energy features read out best."""
        n, d = X.shape
        px = X.reshape(n, -1, 3)
        mu = px.mean(-1, keepdim=True)
        dev = px - mu
        px = mu + torch.sign(dev) * (dev.abs() + 1e-6) ** SATURATION
        px = (0.5 + (px - 0.5) * CONTRAST_GAIN).clamp(0.0, 1.0)
        return px.reshape(n, d)

    @staticmethod
    def _opponent(img):
        r, g, b = img[:, 0:1], img[:, 1:2], img[:, 2:3]
        lum = 0.299 * r + 0.587 * g + 0.114 * b
        rg = r - g
        by = b - 0.5 * (r + g)
        chroma = torch.sqrt(rg * rg + by * by + 1e-6)
        return lum, rg, by, chroma

    def _emaps(self, chan, bank):
        maps = []
        for e, o in bank:
            ks = e.shape[0]
            pad = ks // 2
            re = F.conv2d(chan, e.view(1, 1, ks, ks), padding=pad)
            ro = F.conv2d(chan, o.view(1, 1, ks, ks), padding=pad)
            maps.append(torch.sqrt(re * re + ro * ro + 1e-6))
        return torch.cat(maps, 1)

    def _energy(self, chan, bank, gd):
        return F.adaptive_avg_pool2d(self._emaps(chan, bank), gd).reshape(chan.shape[0], -1)

    def _chroma_hist(self, rg, by, chroma):
        n = rg.shape[0]
        rs = F.adaptive_avg_pool2d(rg, HIST_POOL).reshape(n, -1)
        bs = F.adaptive_avg_pool2d(by, HIST_POOL).reshape(n, -1)
        cs = F.adaptive_avg_pool2d(chroma, HIST_POOL).reshape(n, -1)
        ctr = self._centers.view(1, HIST_BINS, 1)
        wr = torch.exp(-((rs.unsqueeze(1) - ctr) ** 2) / (2 * HIST_SIGMA ** 2)) * cs.unsqueeze(1)
        wb = torch.exp(-((bs.unsqueeze(1) - ctr) ** 2) / (2 * HIST_SIGMA ** 2))
        h = torch.einsum("nip,njp->nij", wr, wb)
        h = h / (h.sum(dim=(1, 2), keepdim=True) + 1e-6) * (HIST_BINS * HIST_BINS)
        return h.reshape(n, -1)

    def _abs_hist(self, chans_kinds, pool=ABS_POOL):
        out = []
        for c, kind in chans_kinds:
            n = c.shape[0]
            cs = F.adaptive_avg_pool2d(c, pool).reshape(n, -1)
            ctr = (self._hc if kind == "abs" else self._oc).view(1, ABS_BINS, 1)
            out.append(torch.exp(-((cs.unsqueeze(1) - ctr) ** 2) / (2 * ABS_SIGMA ** 2)).mean(-1) * ABS_BINS)
        return torch.cat(out, 1)

    def _texcorr(self, lum):
        # kept for reference; not used in the current forward pass (global texture correlations were
        # redundant with the Gabor-energy families on this dataset).
        n = lum.shape[0]
        g = self._emaps(lum, self._lum).mean(dim=(2, 3))
        return torch.einsum("ni,nj->nij", g, g).reshape(n, -1)

    def _cnn(self, lum, rg, by, chroma):
        n = lum.shape[0]
        h = torch.cat([lum, rg, by, chroma], 1)
        h = h - h.mean(dim=(2, 3), keepdim=True)
        feats = []
        for i, w in enumerate(self._cnn_w):
            h = F.conv2d(h, w, padding=w.shape[-1] // 2).clamp_min(0.0)
            h = F.max_pool2d(h, 2)
            feats.append(F.adaptive_avg_pool2d(h, CNN_GRIDS[i]).reshape(n, -1))
        return torch.cat(feats, 1)

    def _rich(self, lum, rg, by, chroma):
        n = lum.shape[0]
        signed = []
        for c in (lum, rg, by, chroma):
            for gd in PYR_GRIDS:
                signed.append(F.adaptive_avg_pool2d(c, gd).reshape(n, -1))
        signed = torch.cat(signed, 1)
        nonneg = torch.cat([
            self._energy(lum, self._lum, LUM_EGRID),
            self._energy(rg, self._opp, OPP_EGRID),
            self._energy(by, self._opp, OPP_EGRID),
            self._chroma_hist(rg, by, chroma),
        ], 1)
        return torch.cat([_spow(signed, P_RICH), nonneg ** P_RICH], 1)

    def _hog(self, chan, cells, blur=0.0):
        """Soft histogram of oriented gradients over a cells x cells grid, magnitude-weighted;
        compressed at P. A classic shape descriptor complementary to the Gabor-energy families.
        An optional Gaussian pre-blur reads out contour orientation at a coarser spatial scale."""
        n = chan.shape[0]
        if blur > 0:
            half = max(1, int(math.ceil(3.0 * blur)))
            c = torch.arange(-half, half + 1, dtype=torch.float32, device=chan.device)
            g = torch.exp(-(c ** 2) / (2.0 * blur ** 2))
            g = g / g.sum()
            k = torch.outer(g, g).view(1, 1, 2 * half + 1, 2 * half + 1)
            chan = F.conv2d(chan, k, padding=half)
        gx = F.pad(chan[:, :, :, 2:] - chan[:, :, :, :-2], (1, 1, 0, 0))
        gy = F.pad(chan[:, :, 2:, :] - chan[:, :, :-2, :], (0, 0, 1, 1))
        mag = torch.sqrt(gx * gx + gy * gy + 1e-6)
        ori = torch.remainder(torch.atan2(gy, gx), math.pi)     # unsigned orientation [0, pi)
        out = []
        for j in range(HOG_BINS):
            c = math.pi * j / HOG_BINS
            d = torch.remainder(ori - c + math.pi / 2, math.pi) - math.pi / 2
            w = torch.exp(-(d * d) / (2 * (math.pi / HOG_BINS * HOG_SIGMA) ** 2)) * mag
            out.append(F.adaptive_avg_pool2d(w, cells).reshape(n, -1))
        return _spow(torch.cat(out, 1), P)

    def _foveal(self, lum, rg, by, chroma):
        n = lum.shape[0]
        H = lum.shape[2]
        fov = []
        for frac, gd, ggd in FOVEA:
            lo = int(H * (0.5 - frac / 2))
            hi = int(H * (0.5 + frac / 2))
            lc, rc, bc, cc = (lum[:, :, lo:hi, lo:hi], rg[:, :, lo:hi, lo:hi],
                              by[:, :, lo:hi, lo:hi], chroma[:, :, lo:hi, lo:hi])
            for c in (lc, rc, bc, cc):
                fov.append(F.adaptive_avg_pool2d(c, gd).reshape(n, -1))
            lem = self._emaps(lc, self._flum)
            fov.append(F.adaptive_avg_pool2d(lem, ggd).reshape(n, -1))
            fov.append(F.adaptive_max_pool2d(lem, ggd).reshape(n, -1))
            for oc in (rc, bc):
                oem = self._emaps(oc, self._opp)
                fov.append(F.adaptive_avg_pool2d(oem, max(2, ggd - 1)).reshape(n, -1))
            # foveal color palette of the object core (marginal soft histograms of the crop)
            fov.append(self._abs_hist([(lc, "abs"), (rc, "opp"), (bc, "opp"), (cc, "abs")],
                                      pool=FOV_HIST_POOL))
        return _spow(torch.cat(fov, 1), P_FOV)

    @torch.no_grad()
    def __call__(self, X):
        X = torch.as_tensor(X).float().clamp_min(0.0) ** INPUT_GAMMA   # retinal light-adaptation gamma
        X = self._saturate(X)                                          # per-pixel saturation boost
        if not self._built:
            self._build(X.device)
        img = self._to_images(X)
        outs = []
        for i in range(0, img.shape[0], SUBCHUNK):
            chunk = img[i:i + SUBCHUNK]
            lum, rg, by, chroma = self._opponent(chunk)
            r, gg, b = chunk[:, 0:1], chunk[:, 1:2], chunk[:, 2:3]
            H = lum.shape[2]
            lo, hi = int(H * 0.375), int(H * 0.625)      # central 0.25 crop for foveal HOG
            lo2, hi2 = int(H * 0.44), int(H * 0.56)      # central 0.12 crop for foveal HOG
            parts = [
                self._rich(lum, rg, by, chroma) * G_RICH,
                self._cnn(lum, rg, by, chroma) ** P * G_CNN,
                self._abs_hist([(lum, "abs"), (r, "abs"), (gg, "abs"), (b, "abs"), (chroma, "abs"),
                                (rg, "opp"), (by, "opp")]) ** P * G_ABS,
                self._foveal(lum, rg, by, chroma) * G_FOV,
                (torch.cat([self._hog(lum, 7), self._hog(rg, 4), self._hog(by, 4),
                            self._hog(lum[:, :, lo:hi, lo:hi], 5),
                            self._hog(lum[:, :, lo2:hi2, lo2:hi2], 4)]
                           + [self._hog(lum, 6, blur=s) for s in HOG_BLUR], 1)) * G_HOG,
            ]
            outs.append(torch.cat(parts, 1))
        return torch.cat(outs, dim=0)


MODEL = Model()
